 "content": "def transform(grid):
    """Erase non-2 cells on the two rows and columns marked by a 2x2 zero block."""
    h, w = len(grid), len(grid[0])
    anchor = None
    for r in range(h - 1):
        for c in range(w - 1):
            if (grid[r][c] == grid[r][c + 1] ==
                    grid[r + 1][c] == grid[r + 1][c + 1] == 0):
                anchor = (r, c)
                break
        if anchor is not None:
            break
    if anchor is None:
        return [row[:] for row in grid]
    r, c = anchor
    marked_rows = {r, r + 1}
    marked_cols = {c, c + 1}
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if (i in marked_rows or j in marked_cols) and out[i][j] != 2:
                out[i][j] = 0
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
